#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=16

# Run from the repo root so .env, data/ and deploy/ resolve.
cd "$(dirname "${BASH_SOURCE[0]}")/.."
export COREPACK_ENABLE_DOWNLOAD_PROMPT=0

# ── Helpers for this wizard ───────────────────────────────────────────────
# node24 runs a command under Node 24 (the repo's version), via mise if the
# default node is something else.
node24() {
  if [[ "$(node --version 2>/dev/null)" == v24.* ]]; then "$@"
  elif command -v mise >/dev/null 2>&1; then mise exec node@24 -- "$@"
  else "$@"; fi
}
pnpm_() { node24 corepack pnpm "$@"; }
railway_() {
  if railway --version >/dev/null 2>&1; then railway "$@"
  else node24 npx -y @railway/cli@5.71.0 "$@"; fi
}
aws_() { aws --profile "$AWS_PROFILE" --region "$AWS_DEFAULT_REGION" "$@"; }
stack_output() {
  aws_ cloudformation describe-stacks --stack-name Duckbill \
    --query "Stacks[0].Outputs[?OutputKey=='$1'].OutputValue" --output text
}
# put_secure NAME VALUE writes an SSM SecureString without the value touching argv.
put_secure() {
  local tmp; tmp=$(mktemp); chmod 600 "$tmp"
  printf '%s' "$2" > "$tmp"
  aws_ ssm put-parameter --name "$1" --type SecureString --overwrite \
    --value "file://$tmp" >/dev/null
  rm -f "$tmp"
  printf '  %s✓ stored%s SSM %s\n' "$GREEN" "$RESET" "$1"
}
ssm_exists() { aws_ ssm get-parameter --name "$1" >/dev/null 2>&1; }
# need VAR "prompt": ask for a secret again if this run doesn't have it yet.
need_secret() { [[ -n "${!1:-}" ]] || ask_secret "$1" "$2"; }
md() { motherduck_token="$1" uv run --frozen python deploy/motherduck.py "${@:2}"; }
local_raw_count() { find data/raw -name '*.jsonl.gz' 2>/dev/null | wc -l | tr -d ' '; }
s3_raw_count() { aws_ s3 ls --recursive "s3://$BUCKET/raw/" | grep -c '\.jsonl\.gz$' || true; }

banner "duckbill: first cloud deployment"

# ──────────────────────────────────────────────────────────────────────────
stage "Check your tools"
say "Everything runs from this machine once; afterwards nothing needs to."
missing=()
for tool in git aws docker uv; do command -v "$tool" >/dev/null 2>&1 || missing+=("$tool"); done
docker info >/dev/null 2>&1 || missing+=("a running Docker daemon (CDK builds the Lambda image)")
node24 node --version 2>/dev/null | grep -q '^v24\.' || missing+=("Node 24 (mise install node@24)")
if (( ${#missing[@]} )); then
  for m in "${missing[@]}"; do warn "missing: $m"; done
  exit 1
fi
step "Installing Python and Node dependencies from the lockfiles..."
uv sync --frozen >/dev/null
pnpm_ install --frozen-lockfile >/dev/null
printf '  %s✓%s tools ready\n' "$GREEN" "$RESET"
[[ -d data/raw ]] || warn "no data/raw here: stage 5 will have nothing to upload"
pause

# ──────────────────────────────────────────────────────────────────────────
stage "AWS account"
say "Pick the AWS CLI profile to deploy with. It needs admin rights in the account."
note "No profile yet? Run 'aws configure --profile duckbill' (access key) or"
note "'aws configure sso' (IAM Identity Center) in another terminal, then come back."
ask AWS_PROFILE "AWS profile [default]:"
AWS_PROFILE=${AWS_PROFILE:-default}
ask AWS_DEFAULT_REGION "AWS region [eu-west-2, London]:"
AWS_DEFAULT_REGION=${AWS_DEFAULT_REGION:-eu-west-2}
export AWS_PROFILE AWS_DEFAULT_REGION AWS_REGION="$AWS_DEFAULT_REGION"
if ! identity=$(aws_ sts get-caller-identity --query '[Account, Arn]' --output text 2>&1); then
  warn "can't use profile $AWS_PROFILE: $identity"
  note "For SSO profiles, run: aws sso login --profile $AWS_PROFILE"
  exit 1
fi
ACCOUNT=${identity%%[[:space:]]*}
say "Signed in as ${identity#*[[:space:]]}"
confirm "Deploy duckbill into account $ACCOUNT ($AWS_DEFAULT_REGION)?" || exit 1
write_env AWS_PROFILE "$AWS_PROFILE"
write_env AWS_DEFAULT_REGION "$AWS_DEFAULT_REGION"

# ──────────────────────────────────────────────────────────────────────────
stage "Deploy the AWS stack"
say "This creates the raw S3 bucket, the daily ingest and dbt Lambda functions,"
say "a 05:00 UTC schedule and failure alarms (deploy/cdk/lib/stack.ts)."
note "It costs pennies a month: Lambda and SSM stay inside the free tier."
ask DUCKBILL_ALERT_EMAIL "Email address for failure alarms:"
write_env DUCKBILL_ALERT_EMAIL "$DUCKBILL_ALERT_EMAIL"
# The ingest function reserves 1 concurrent run (single-use refresh tokens), and
# Lambda keeps 100 of the account limit unreserved, so the limit must exceed 100.
limit=$(aws_ lambda get-account-settings --query AccountLimit.ConcurrentExecutions --output text)
if (( limit <= 100 )); then
  warn "this account's Lambda concurrency limit is $limit; reserving 1 needs more than 100."
  note "Request an increase: Service Quotas → AWS Lambda → Concurrent executions, then re-run."
  exit 1
fi
confirm "Bootstrap CDK (if needed) and deploy? Building the image takes a few minutes." || exit 1
(
  cd deploy/cdk
  pnpm_ exec cdk bootstrap "aws://$ACCOUNT/$AWS_DEFAULT_REGION"
  pnpm_ exec cdk deploy Duckbill -c "alertEmail=$DUCKBILL_ALERT_EMAIL" --require-approval broadening
)
BUCKET=$(stack_output BucketName)
INGEST_FN=$(stack_output IngestFunctionName)
DBT_FN=$(stack_output DbtFunctionName)
printf '  %s✓ deployed%s bucket %s\n' "$GREEN" "$RESET" "$BUCKET"
step "AWS has emailed $DUCKBILL_ALERT_EMAIL: click 'Confirm subscription' so alarms reach you."
pause "Press Enter once confirmed (or later; alarms just won't email until you do)"

# ──────────────────────────────────────────────────────────────────────────
stage "Monzo app credentials → SSM"
say "The ingest function needs your Monzo OAuth client to refresh the token."
MONZO_CLIENT_ID=$(_existing MONZO_CLIENT_ID || true)
MONZO_CLIENT_SECRET=$(_existing MONZO_CLIENT_SECRET || true)
[[ -n "$MONZO_CLIENT_ID" ]] || ask MONZO_CLIENT_ID "Monzo client ID (oauth2client_…):"
[[ -n "$MONZO_CLIENT_SECRET" ]] || ask_secret MONZO_CLIENT_SECRET "Monzo client secret:"
export MONZO_CLIENT_ID MONZO_CLIENT_SECRET  # for 'duckbill login' in stage 10
client_json=$(MONZO_CLIENT_ID="$MONZO_CLIENT_ID" MONZO_CLIENT_SECRET="$MONZO_CLIENT_SECRET" python3 -c \
  'import json, os; print(json.dumps({"client_id": os.environ["MONZO_CLIENT_ID"], "client_secret": os.environ["MONZO_CLIENT_SECRET"]}))')
put_secure /duckbill/monzo-client "$client_json"
unset client_json
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Raw history → S3"
# Stop the local sync first: it would add raw files and move the checkpoint
# after the upload, and with .env pointing at SSM it would be a second writer
# of the token.
if systemctl --user is-enabled duckbill-sync.timer >/dev/null 2>&1 \
  || systemctl --user is-active duckbill-sync.timer >/dev/null 2>&1 \
  || systemctl --user is-active duckbill-sync.service >/dev/null 2>&1; then
  warn "the local systemd sync has to stop before history moves to the cloud"
  confirm "Disable duckbill-sync.timer and stop any running sync?" || exit 1
  systemctl --user disable --now duckbill-sync.timer
  systemctl --user stop duckbill-sync.service
fi
say "Raw files are your only copy of history older than Monzo's 90 days."
say "They go to s3://$BUCKET/raw (versioned). The local copy stays until stage 16."
say "Local raw files: $(local_raw_count)"
if [[ "$(local_raw_count)" -gt 0 ]] && confirm "Upload raw files and sync state to S3?"; then
  aws_ s3 sync --only-show-errors data/raw "s3://$BUCKET/raw"
  if [[ -f data/state/sync_state.json ]]; then
    aws_ s3 cp --only-show-errors data/state/sync_state.json "s3://$BUCKET/state/sync_state.json"
  fi
fi
say "Raw files in S3: $(s3_raw_count)"
write_env DUCKBILL_STORAGE_URI "s3://$BUCKET"
note "Local duckbill commands now read and write raw in S3."
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Monzo token → SSM"
say "Monzo refresh tokens are single use, so exactly one place may hold the token."
say "From here that's SSM, used only by the ingest function."
TOKEN_FILE=data/secrets/monzo_token.json
if [[ -f "$TOKEN_FILE" ]]; then
  ssm_exists /duckbill/monzo-token && warn "SSM already holds a token; this replaces it with the local one"
  if confirm "Move the local token to SSM and delete the local copy?"; then
    aws_ ssm put-parameter --name /duckbill/monzo-token --type SecureString --overwrite \
      --value "file://$TOKEN_FILE" >/dev/null
    stored=$(aws_ ssm get-parameter --name /duckbill/monzo-token --with-decryption \
      --query Parameter.Value --output text)
    if [[ "$stored" == "$(cat "$TOKEN_FILE")" ]]; then
      unset stored
      rm -f "$TOKEN_FILE"
      printf '  %s✓ moved%s token to SSM /duckbill/monzo-token, local copy deleted\n' "$GREEN" "$RESET"
    else
      warn "SSM copy doesn't match; kept $TOKEN_FILE. Re-run this stage."
      exit 1
    fi
  fi
elif ! ssm_exists /duckbill/monzo-token; then
  warn "no token anywhere yet"
fi
write_env DUCKBILL_TOKEN_PARAMETER /duckbill/monzo-token
note "'uv run duckbill login' now writes its token to SSM and raw to S3."
note "Don't run 'duckbill sync' locally: the daily function owns the token."
pause

# ──────────────────────────────────────────────────────────────────────────
stage "MotherDuck account (EU)"
open_url "https://app.motherduck.com/"
step "Sign up or sign in (free Lite plan)."
step "If you're creating the organization now and are asked for a region, pick"
step "Europe: Dublin (eu-west-1), or Frankfurt. The region can't be changed later."
step "Open a new SQL cell, run:  select current_user;  and copy the result."
ask DUCKBILL_MOTHERDUCK_USER "Your MotherDuck username:"
write_env DUCKBILL_MOTHERDUCK_USER "$DUCKBILL_MOTHERDUCK_USER"

# ──────────────────────────────────────────────────────────────────────────
stage "MotherDuck service accounts"
say "Two accounts: a writer for the dbt function, and a reader for the web app."
say "The reader owns nothing and sees the warehouse only through a read-only share."
step "In MotherDuck: Settings → Service Accounts → Create service account."
step "Username: duckbill_writer → Create service account."
step "Click duckbill_writer → Create token → name 'lambda', type Read/Write → Create, copy it."
ask_secret MD_WRITER_TOKEN "Paste the duckbill_writer token:"
put_secure /duckbill/motherduck-token "$MD_WRITER_TOKEN"
step "Create another service account: duckbill_reader."
step "Click duckbill_reader → Create token → name 'railway', type Read/Write → Create, copy it."
note "Read/Write because read-scaling tokens can't attach shares; the share itself is read-only."
ask_secret MD_READER_TOKEN "Paste the duckbill_reader token:"
note "Neither token is saved on this machine: the writer's is in SSM, the reader's goes to Railway."

# ──────────────────────────────────────────────────────────────────────────
stage "MotherDuck share"
say "As duckbill_writer: create the duckbill database and a hidden, read-only,"
say "auto-updating share of it for duckbill_reader and you."
need_secret MD_WRITER_TOKEN "Paste the duckbill_writer token again:"
share_url=$(md "$MD_WRITER_TOKEN" share --grant duckbill_reader --grant "$DUCKBILL_MOTHERDUCK_USER" | tail -n1)
[[ "$share_url" == md:_share/* ]] || { warn "unexpected output: $share_url"; exit 1; }
write_env DUCKBILL_MOTHERDUCK_SHARE "$share_url"
step "To browse it in the MotherDuck UI as yourself, run once in a SQL cell:"
say "    ATTACH '$share_url' AS duckbill;"
pause

# ──────────────────────────────────────────────────────────────────────────
stage "First cloud run"
say "Running the ingest function now. It syncs Monzo into S3, then starts dbt,"
say "which builds and publishes to MotherDuck."
started=$(date -u +%Y-%m-%dT%H:%M:%S+00:00)
out=$(mktemp)
for attempt in 1 2; do
  aws_ lambda invoke --function-name "$INGEST_FN" --cli-read-timeout 360 "$out" \
    --query FunctionError --output text > "$out.err" || true
  if grep -q ReauthRequired "$out"; then
    warn "Monzo needs a fresh login (the stored token can't be refreshed)."
    if (( attempt == 1 )) && confirm "Run 'uv run duckbill login' now? Approve in the Monzo app when asked."; then
      uv run --frozen duckbill login --no-transform
      continue
    fi
    exit 1
  fi
  break
done
if [[ "$(cat "$out.err")" != "None" ]]; then
  warn "ingest failed: $(head -c 600 "$out")"; exit 1
fi
say "ingest: $(head -c 300 "$out")"
rm -f "$out" "$out.err"
need_secret MD_READER_TOKEN "Paste the duckbill_reader token again:"
step "Waiting for dbt to publish (up to ~12 minutes; the share can lag 5)..."
published=false
for _ in $(seq 1 24); do
  if md "$MD_READER_TOKEN" check --share "$DUCKBILL_MOTHERDUCK_SHARE" --since "$started"; then
    published=true; break
  fi
  sleep 30
done
if ! $published; then
  logs=$(aws_ lambda get-function-configuration --function-name "$DBT_FN" --query LoggingConfig.LogGroup --output text)
  warn "no new build yet. Check: aws logs tail $logs --since 30m --profile $AWS_PROFILE"
  confirm "Continue anyway?" || exit 1
fi

# ──────────────────────────────────────────────────────────────────────────
stage "Clerk application"
open_url "https://dashboard.clerk.com/"
step "Create application → name it duckbill."
step "Sign-in options: turn on Google, turn off Email and everything else → Create."
step "Open the API keys page and copy the Publishable key (pk_test_…)."
ask CLERK_PUBLISHABLE_KEY "Publishable key:"
write_env CLERK_PUBLISHABLE_KEY "$CLERK_PUBLISHABLE_KEY"
step "Copy the Secret key (sk_test_…)."
ask_secret CLERK_SECRET_KEY "Secret key:"
note "This is a Development instance, fine for one user on a railway.app domain."
note "A Production instance needs a domain you own (see README → Deploying)."

# ──────────────────────────────────────────────────────────────────────────
stage "Code on GitHub"
say "Railway builds from GitHub, so this branch has to be pushed."
BRANCH=$(git branch --show-current)
REPO=$(git remote get-url origin | sed -E 's#^(git@github.com:|https://github.com/)##; s#\.git$##')
[[ -z "$(git status --porcelain)" ]] || warn "uncommitted changes won't be deployed"
if [[ "$(git rev-parse HEAD)" == "$(git rev-parse "@{u}" 2>/dev/null || true)" ]]; then
  say "$REPO@$BRANCH is up to date on GitHub."
elif confirm "Push $BRANCH to $REPO?"; then
  git push -u origin "$BRANCH"
else
  warn "Railway will deploy whatever is on GitHub at $BRANCH"
fi
note "Railway's GitHub app needs access to $REPO: you'll be asked on first use."

# ──────────────────────────────────────────────────────────────────────────
stage "Railway project and domain"
RAILWAY_DOMAIN=$(_existing DUCKBILL_RAILWAY_DOMAIN || true)
if [[ -n "$RAILWAY_DOMAIN" ]] && confirm "Railway is already set up at $RAILWAY_DOMAIN. Keep it?"; then
  :
else
  railway_ whoami >/dev/null 2>&1 || railway_ login
  if ! railway_ status >/dev/null 2>&1; then
    confirm "Create a Railway project called duckbill?" || exit 1
    railway_ init --name duckbill
  fi
  railway_ add --service duckbill --repo "$REPO" --branch "$BRANCH" \
    || warn "couldn't add the service (already there?); continuing"
  domain_out=$(railway_ domain --service duckbill --port 8080 2>&1 || true)
  RAILWAY_DOMAIN=$(grep -oE '[a-z0-9.-]+\.up\.railway\.app' <<<"$domain_out" | head -n1 || true)
  if [[ -z "$RAILWAY_DOMAIN" ]]; then
    say "$domain_out"
    ask RAILWAY_DOMAIN "Couldn't read the domain; paste it (xxx.up.railway.app):"
  fi
fi
write_env DUCKBILL_RAILWAY_DOMAIN "$RAILWAY_DOMAIN"
note "The first deploy will fail its health check until stage 14 sets Clerk up: expected."

# ──────────────────────────────────────────────────────────────────────────
stage "Railway variables"
need_secret MD_READER_TOKEN "Paste the duckbill_reader token again:"
need_secret CLERK_SECRET_KEY "Paste the Clerk secret key again:"
OWNER=$(_existing DUCKBILL_OWNER_USER_ID || true)
set_railway() { railway_ variable set --service duckbill --skip-deploys "$@" >/dev/null; }
set_railway PORT=8080 \
  "DUCKBILL_ALLOWED_HOSTS=$RAILWAY_DOMAIN" \
  "DUCKBILL_WAREHOUSE=$DUCKBILL_MOTHERDUCK_SHARE" \
  "CLERK_PUBLISHABLE_KEY=$CLERK_PUBLISHABLE_KEY"
printf '%s' "$MD_READER_TOKEN" | set_railway MOTHERDUCK_TOKEN --stdin
printf '%s' "$CLERK_SECRET_KEY" | set_railway CLERK_SECRET_KEY --stdin
# Until you've signed in once nobody is the owner, so every API call gets a 403.
railway_ variable set --service duckbill "DUCKBILL_OWNER_USER_ID=${OWNER:-pending}" >/dev/null
printf '  %s✓ set%s Railway variables; a deploy has started\n' "$GREEN" "$RESET"
note "Secrets went over stdin, not the command line."

# ──────────────────────────────────────────────────────────────────────────
stage "Sign in and claim ownership"
say "Wait for the deploy to go green in Railway (a few minutes), then:"
open_url "https://$RAILWAY_DOMAIN"
step "Continue with Google. You'll see 'Not allowed' until the next step."
pause "Press Enter once you've signed in"
# The key goes to curl as config on stdin, not in its argv.
users=$(printf 'header = "Authorization: Bearer %s"\n' "$CLERK_SECRET_KEY" \
  | curl -fsS -K - "https://api.clerk.com/v1/users?limit=10" \
  | python3 -c 'import json, sys
for u in json.load(sys.stdin):
    emails = [e["email_address"] for e in u.get("email_addresses", [])]
    print(u["id"], ", ".join(emails))') || { warn "couldn't list Clerk users; check the secret key"; exit 1; }
[[ -n "$users" ]] || { warn "no users yet: sign in on the site first, then re-run"; exit 1; }
say "Users in your Clerk app:"
while read -r line; do note "  $line"; done <<<"$users"
if [[ "$(wc -l <<<"$users")" -eq 1 ]] && confirm "Make ${users%% *} the owner?"; then
  DUCKBILL_OWNER_USER_ID=${users%% *}
else
  ask DUCKBILL_OWNER_USER_ID "Paste your user id (user_…):"
fi
write_env DUCKBILL_OWNER_USER_ID "$DUCKBILL_OWNER_USER_ID"
railway_ variable set --service duckbill "DUCKBILL_OWNER_USER_ID=$DUCKBILL_OWNER_USER_ID" >/dev/null
printf '  %s✓ set%s owner; redeploying\n' "$GREEN" "$RESET"
step "Once this deploy is live, reload https://$RAILWAY_DOMAIN: your dashboard should load."
step "Optional: in the Clerk dashboard, set sign-ups to restricted so nobody else can"
step "create an account (look under User & authentication → Restrictions)."
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Tidy up this machine"
say "Nothing needs to run here any more."
if [[ -d data/raw ]]; then
  # A dry-run sync lists every local file S3 lacks or holds at a different size.
  missing_in_s3=$(aws_ s3 sync --dryrun data/raw "s3://$BUCKET/raw")
  if [[ -z "$missing_in_s3" ]]; then
    say "All $(local_raw_count) local raw files are in S3."
    confirm "Delete the local raw copy (data/raw)? S3 keeps it, versioned." && rm -rf data/raw
  else
    warn "some local raw files aren't in S3 yet; keeping data/raw:"
    note "$(head -n 5 <<<"$missing_in_s3")"
  fi
fi
[[ -f data/state/sync_state.json ]] && confirm "Delete local sync state (now in S3)?" && rm -f data/state/sync_state.json
for backup in data/warehouse.duckdb-v2.bak data-demo/warehouse.duckdb-v2.bak; do
  [[ -f "$backup" ]] && confirm "Delete old DuckDB 2.0 backup $backup?" && rm -f "$backup"
done
for unit in ~/.config/systemd/user/duckbill-sync.service ~/.config/systemd/user/duckbill-sync.timer; do
  [[ -f "$unit" ]] && confirm "Remove $unit?" && rm -f "$unit"
done
note "data/warehouse.duckdb stays for local poking; 'uv run duckbill transform' rebuilds it from S3."
pause

finish
}

run_wizard "$@"; exit
